<script setup lang="ts">
import {onMounted,ref,onUnmounted} from 'vue';import type {RequestFn} from './media';import {date} from './lib';
const props=defineProps<{request:RequestFn}>();const administrators=ref<Record<string,any>[]>([]);const config=ref<Record<string,any>>({enabled:false,mode:'notify_only',token:'',principals:[]}),version=ref(0),configured=ref(false),scopes=ref<Record<string,string>>({}),status=ref<Record<string,any>>({}),busy=ref(false),error=ref(''),notice=ref(''),clear=ref(false);
async function load(){const d=await props.request('admin/telegram');const team=await props.request('admin/administrators');administrators.value=Array.isArray(team)?team:(team.items||[]);config.value={...d.config,principals:d.config.principals||[],token:''};version.value=d.version;configured.value=d.configured;scopes.value=d.scopes;status.value=d.status}
async function act(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
async function save(){await act(async()=>{const d=await props.request('admin/telegram','PUT',{...config.value,version:version.value,clear_token:clear.value});await load();clear.value=false;notice.value=d.message})}
async function command(kind:string){await act(async()=>{const d=await props.request('admin/telegram/'+kind,'POST',{});notice.value=d.message;status.value=(await props.request('admin/telegram')).status})}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{void act(load);timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value)void props.request('admin/telegram').then(d=>status.value=d.status).catch(()=>{})},30000)});onUnmounted(()=>{clearInterval(timer);config.value.token=''})
</script>
<template><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div><section class="panel"><h3>运营 Telegram 机器人</h3><p class="muted">仅主管理员能编辑接入和权限。这里的授权对象可查询整个购买面板中已授权的运营数据，并非购买用户的个人绑定。</p><form @submit.prevent="save"><div class="fields"><label>接入方式<select v-model="config.mode"><option value="notify_only">仅发送通知 · 可复用已有机器人</option><option value="polling">独立机器人 · 通知和查询命令</option></select></label><label>Bot Token<input v-model="config.token" type="password" autocomplete="off" :placeholder="configured?'已配置；留空保留':'填写机器人令牌'"></label><label class="multi"><input type="checkbox" v-model="config.enabled">启用此机器人</label><label class="multi"><input type="checkbox" v-model="clear">删除已保存的令牌并停用</label></div><p class="form-note">独立命令模式不能与星枢原后台或其他程序共用同一个轮询机器人；已有 Webhook 不会被自动删除。复用原机器人时选“仅发送通知”，避免抢占原有命令。</p><p v-if="config.mode==='notify_only'" class="alert">当前仅通知，不接收命令或核款按钮。需要机器人核款时，请选用专用机器人并切换“独立机器人 · 通知和查询命令”。</p><h3>授权私聊用户</h3><p class="muted">使用 Telegram 数字用户 ID，接收者需先在私聊中启动机器人。默认通知只含订单、金额和核验状态，完整红包口令需另行授予查询权限。</p><article v-for="(p,index) in config.principals" :key="index" class="panel"><div class="fields"><label>备注<input v-model="p.label" maxlength="60"></label><label>Telegram 用户数字 ID<input v-model.number="p.user_id" inputmode="numeric" type="number" min="1" required></label><label class="multi"><input type="checkbox" v-model="p.notify">接收所授权的订单 / 付款通知</label></div><div class="flags"><label v-for="(name,id) in scopes" :key="id" class="multi"><input v-model="p.scopes" type="checkbox" :value="id" @change="['approve','redpacket'].includes(String(id))&&p.scopes.includes(id)&&!p.scopes.includes('payments')&&p.scopes.push('payments')">{{name}}</label></div><label v-if="p.scopes.includes('approve')">绑定核款管理员<select v-model="p.administrator_id" required><option value="" disabled>选择后台管理员</option><option v-for="a in administrators.filter(a=>a.status==='active'&&(a.is_owner||a.admin_scopes?.includes('payments')))" :key="a.id" :value="a.id">{{a.name}} · {{a.email}}</option></select><small>停用或撤销此管理员的核款权限后，机器人审批立即失效。</small></label><button type="button" @click="config.principals.splice(index,1)">移除此授权</button></article><div class="actions"><button type="button" :disabled="config.principals.length>=20" @click="config.principals.push({label:'',user_id:0,notify:true,scopes:['orders','payments']})">＋ 添加授权对象</button><button class="primary" :disabled="busy">保存机器人配置</button></div></form></section><section class="panel"><h3>连接与通知状态</h3><div class="stats"><div><span>机器人</span><strong>{{status.username?'@'+status.username:'尚未验证'}}</strong></div><div><span>待投递 / 失败 / 已完成</span><strong>{{status.queued||0}} / {{status.failed||0}} / {{status.sent||0}}</strong></div></div><p>最近轮询 {{date(status.last_poll_at)}}<small class="block-note">仅通知模式不需要接收命令轮询。</small></p><p v-if="status.last_error" class="alert error">{{status.last_error}}</p><div class="actions"><button :disabled="busy||!configured" @click="command('check')">验证令牌与接入条件</button><button :disabled="busy||!configured||config.mode!=='polling'" @click="command('commands')">设置查询命令菜单</button><button :disabled="busy||!status.failed" @click="command('retry')">重试失败通知</button></div><p class="muted">支持订单列表按钮，或 /order 订单前8位、/redpacket 订单前8位；也支持 /help、/overview、/orders、/payments。每条命令均再次校验数字用户 ID、私聊和权限；已授权的核款管理员可以在机器人二次确认后批准口令红包；机器人不代领红包，静态收款码也可从订单按钮核验：回复真实流水号、金额和北京时间，再二次确认。</p></section></template>
